/* From Uiverse.io by mrhyddenn - Tags: button, download */
.__UIV_SCOPE__ .button {
  -moz-appearance: none;
  -webkit-appearance: none;
  appearance: none;
  border: none;
  background: none;
  color: #0f1923;
  cursor: pointer;
  position: relative;
  padding: 8px;
  margin-bottom: 20px;
  text-transform: uppercase;
  font-weight: bold;
  font-size: 14px;
  transition: all .15s ease;
}

.__UIV_SCOPE__ .button::before,
.__UIV_SCOPE__ .button::after {
  content: '';
  display: block;
  position: absolute;
  right: 0;
  left: 0;
  height: calc(50% - 5px);
  border: 1px solid #7D8082;
  transition: all .15s ease;
}

.__UIV_SCOPE__ .button::before {
  top: 0;
  border-bottom-width: 0;
}

.__UIV_SCOPE__ .button::after {
  bottom: 0;
  border-top-width: 0;
}

.__UIV_SCOPE__ .button:active,
.__UIV_SCOPE__ .button:focus {
  outline: none;
}

.__UIV_SCOPE__ .button:active::before,
.__UIV_SCOPE__ .button:active::after {
  right: 3px;
  left: 3px;
}

.__UIV_SCOPE__ .button:active::before {
  top: 3px;
}

.__UIV_SCOPE__ .button:active::after {
  bottom: 3px;
}

.__UIV_SCOPE__ .button_lg {
  position: relative;
  display: block;
  padding: 10px 20px;
  color: #fff;
  background-color: #0f1923;
  overflow: hidden;
  box-shadow: inset 0px 0px 0px 1px transparent;
}

.__UIV_SCOPE__ .button_lg::before {
  content: '';
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  width: 2px;
  height: 2px;
  background-color: #0f1923;
}

.__UIV_SCOPE__ .button_lg::after {
  content: '';
  display: block;
  position: absolute;
  right: 0;
  bottom: 0;
  width: 4px;
  height: 4px;
  background-color: #0f1923;
  transition: all .2s ease;
}

.__UIV_SCOPE__ .button_sl {
  display: block;
  position: absolute;
  top: 0;
  bottom: -1px;
  left: -8px;
  width: 0;
  background-color: #ff4655;
  transform: skew(-15deg);
  transition: all .2s ease;
}

.__UIV_SCOPE__ .button_text {
  position: relative;
}

.__UIV_SCOPE__ .button:hover {
  color: #0f1923;
}

.__UIV_SCOPE__ .button:hover .button_sl {
  width: calc(100% + 15px);
}

.__UIV_SCOPE__ .button:hover .button_lg::after {
  background-color: #fff;
}
